package com.lucento.app.core.banks

import com.lucento.app.core.money.Money
import com.lucento.app.data.repository.FakeTransactionDao
import com.lucento.app.data.repository.FakeWalletDao
import com.lucento.app.data.repository.WalletRepository
import com.lucento.app.domain.WalletType
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.test.runTest
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

/**
 * The bundled registry as shipped (assets/banks/institutions.json, generated by tools/institutions) and the wallet's
 * institution link. Display only: nothing here touches money.
 */
class InstitutionRegistryTest {

    private val asset = File("src/main/assets/banks/institutions.json")
    private val registry by lazy { InstitutionRegistry.parse(asset.readText()) }
    private val drawable = File("src/main/res/drawable")
    private val nodpi = File("src/main/res/drawable-nodpi")
    /** id -> drawable name, as the generated InstitutionArt.kt maps them (identical icons share one drawable). */
    private val art by lazy {
        Regex("\"([a-z0-9_]+)\" to R\\.drawable\\.([a-z0-9_]+)").findAll(
            File("src/main/java/com/lucento/app/core/banks/InstitutionArt.kt").readText()
        ).groupBy({ it.groupValues[2].split('_')[1] }, { it.groupValues[1] to it.groupValues[2] }) // logo / icon / app
            .mapValues { (_, pairs) -> pairs.toMap() }
    }

    @Test fun `the shipped registry parses and every id, colour and art file is consistent`() {
        assertEquals(380, registry.all.size) // 386 in the library minus the 6 card networks, which are never a wallet
        assertTrue(registry.all.all { it.id.matches(Regex("^[a-z]{2,3}_[a-z0-9_]+$")) })
        assertEquals(registry.all.size, registry.all.map { it.id }.toSet().size)
        val hex = Regex("^#[0-9A-Fa-f]{6}$")
        registry.all.forEach { inst ->
            assertTrue(inst.id, inst.card.stops.isNotEmpty() && inst.card.stops.all(hex::matches))
            assertTrue(inst.id, hex.matches(inst.card.ink) && hex.matches(inst.card.monogram.bg) && hex.matches(inst.card.monogram.fg))
            when (inst.icon.kind) {
                "vector" -> assertTrue(inst.id, File(drawable, "${art.getValue("icon").getValue(inst.id)}.xml").exists())
                "bitmap" -> assertTrue(inst.id, File(nodpi, "${art.getValue("app").getValue(inst.id)}.webp").exists())
                "monogram" -> assertTrue(inst.id, inst.icon.monogram != null)
                else -> error("unknown icon kind ${inst.icon.kind}")
            }
            if (inst.card.logo != null) assertTrue(inst.id, File(drawable, "${art.getValue("logo").getValue(inst.id)}.xml").exists())
        }
    }

    @Test fun `card ink meets 4_5 to 1 against every stop of its face`() {
        registry.all.forEach { inst ->
            inst.card.stops.forEach { stop ->
                val ratio = contrast(inst.card.ink, stop)
                assertTrue("${inst.id} ink ${inst.card.ink} on $stop = $ratio", ratio >= 4.5)
            }
        }
    }

    @Test fun `white logos never sit on a white plate`() {
        registry.all.mapNotNull { it.card.logo?.let { logo -> it.id to logo } }.filter { it.second.white }.forEach { (id, logo) ->
            assertTrue(id, logo.plate != "light" || logo.white) // InstitutionCardMark swaps a light plate to navy for white logos
        }
        assertTrue(registry["my_cimb"]!!.card.logo!!.white)
    }

    @Test fun `search finds by any word, ignores accents and case, and puts the home country first`() {
        assertEquals("ph_bdo", registry.search("bdo").first().id)
        assertTrue(registry.search("societe").any { it.id == "fr_societe_generale" }) // "Société Générale"
        val chase = registry.search("chase", country = "GB")
        assertEquals("gb_chase_uk", chase.first().id)
        assertTrue(chase.any { it.id == "us_chase" })
        val home = registry.search("", country = "PH")
        assertTrue(home.isNotEmpty() && home.all { it.country == "PH" })
        assertTrue(registry.search("zzzz-no-such-bank").isEmpty())
        assertNull(registry["xx_unknown"])
        assertNull(registry[null])
    }

    @Test fun `a wallet keeps its institution through edits, and an edit that doesn't know about it keeps it too`() = runTest {
        val dao = FakeWalletDao().also { it.transactions = FakeTransactionDao() }
        val wallets = WalletRepository(dao, FakeTransactionDao(), clock = { 1L })
        val id = (wallets.create("Everyday", WalletType.BANK, Money(0, "PHP"), institutionId = "ph_bdo") as WalletRepository.SaveResult.Saved).id
        assertEquals("ph_bdo", wallets.observeWallets().first().single().institutionId)

        wallets.update(id, "Everyday account", WalletType.BANK, Money(0, "PHP")) // older caller: institution untouched
        assertEquals("ph_bdo", dao.getById(id)!!.institutionId)

        wallets.update(id, "Everyday account", WalletType.BANK, Money(0, "PHP"), null, institutionId = null) // removed
        assertNull(dao.getById(id)!!.institutionId)

        wallets.update(id, "Everyday account", WalletType.BANK, Money(0, "PHP"), null, institutionId = "Not An Id!")
        assertNull("only registry-shaped ids are stored", dao.getById(id)!!.institutionId)
    }

    private fun contrast(a: String, b: String): Double {
        fun lum(hex: String): Double {
            val c = listOf(1, 3, 5).map { hex.substring(it, it + 2).toInt(16) / 255.0 }
                .map { if (it <= 0.03928) it / 12.92 else Math.pow((it + 0.055) / 1.055, 2.4) }
            return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2]
        }
        val (hi, lo) = listOf(lum(a), lum(b)).sortedDescending()
        return (hi + 0.05) / (lo + 0.05)
    }
}
